					sub = "T1-T8: the item level each tier needs and the odds.",
					sections = {
						{
							h = "Tiers",
							p = {"A modifier rolls among the best 5 tiers its item level allows, weighted (higher tiers are rarer)."},
							cols = {"Tier", "Item level", "Weight"},
							w = {30, 35, 35},
