					sub = "Where the item level of a drop comes from.",
					sections = {
						{
							h = "Item level",
							p = {"A drop's item level follows the monster's level along the curve below (straight lines in between), then: Normal +0, Magic +2, Rare +4, Legendary +7, Boss +10; inside a rift +1 per rift tier (at most +15); an Omen arena +15 more; at most 150.", "Fixed: world boss drops and rewards 145, store gear 60, the tutorial's gear 5.", "Orbs keep the item level."},
							cols = {"Monster level", "Item level"},
