					name = "Prefixes and suffixes",
					color = "#d6c9ae",
					sub = "What a prefix and a suffix are.",
					sections = {
						{
							h = "Sides",
							p = {"Prefixes: damage and defence (skills, critical hits, weapon elements, block, dodge, reflect, thorns, penetration, ailments...).", "Suffixes: utility, resistances and speed (absorbs, leech, attack and movement speed, life and mana on kill or hit, find, experience...).", "A new item is rolled until its count or both sides are full; the Orb of Grafting only adds on a side that is open. An Orb of Ruin can give one extra slot on one side."}
						}
					}
				},
				{
					id = "basics:conquest",
					name = "Conquest Tokens",
					color = "#d6c9ae",
					sub = "The sure path: tokens for every boss and clear, any item you have seen for sale.",
					sections = {
						{
							h = "Earning",
							p = {"Every boss you help slay (damage, last hit, or a party member within range), every sealed rift, dungeon clear, Ember Descent run and invasion reward gives Conquest Tokens. Each source has a daily limit; the window's Progress tab shows today's tokens."},
							cols = {"Source", "Tokens", "Per day"},
