								{"Set pieces", "+5% of the base per miss", "x4"},
								{"Raid uniques", "+25% of the base per miss", "x5"}
							}
						}
					}
				},
				{
					id = "basics:quality",
					name = "Quality, binding and ruin",
					color = "#d6c9ae",
					sub = "Whetstones, bound modifiers and the Orb of Ruin.",
					sections = {
						{
							h = "Quality",
							p = {"Each Whetstone adds 1% quality, up to 20% (30% from Divine). Every modifier value is multiplied by (100 + quality) / 100, rounded."},
							links = {"orb:whetstone"}
						},
						{
							h = "Binding",
							p = {"A bound modifier is left alone by Tempering, Unmaking, Excision, Reforging and Upheaval. Only an Orb of Erasure frees it (and wipes the item). An item with a bound modifier refuses the Orb of Fate."},
							links = {"orb:binding"}
						},
						{
							h = "Corruption",
							p = {"The Void Orb corrupts a Rare or better item for good: no orb changes it afterwards, and the tooltip shows Corrupted. Then: 28% nothing else happens, 20% a modifier rises one tier, 20% a corrupted implicit modifier, 8% quality 30%, 7% one more socket (up to 3), 8% every modifier rolls again, 4% one rarity up (up to Divine), 5% a modifier falls 2 tiers. A locked or store item is refused."},
							links = {"orb:void"}
						},
						{
							h = "Ruin",
							p = {"The Orb of Ruin: 40% the item improves (60% of those one tier more on every unbound modifier, else an extra modifier above the side limit, once per item), 60% nothing happens. It never ruins an item (items ruined before stay ruined). For a sure step up, the Conquest vendor's refinement raises a worn item one rarity (up to Legendary), keeps its modifiers and adds one."},
							links = {"orb:ruin"}
						}
					}
				},
				{
					id = "basics:pace",
					name = "Pack combat",
					color = "#d6c9ae",
					sub = "Monsters come in packs and die fast: kill groups, not one at a time.",
					sections = {
						{
							h = "In short",
							p = {"Hunting monsters have much less health and come in bigger packs. Pull a group and kill it together: area spells and cleaves matter.", "Experience and loot per kill are lower by the same share, so experience and gold per hour stay where they were. Kill counts (bounties, bestiary, tasks, achievements) need more kills by the same share.", "Multikill: kills each within 3 s of the one before form a chain; the whole chain's experience gets 4 kills +10%, 6 kills +20%, 8 kills +30%, 9 kills +40%.", "Bosses, rifts, the Ember Descent, the tower, invasions, arena, battleground and PvP are not changed."}
						},
						{
							h = "By hunting level",
							p = {"Health, experience per kill, loot per kill and the monster's damage to you, in percent of the monster's own numbers. Monsters with a level of their own (late game, generated areas and dungeons) use the second set, on top of the health and experience their level already gives them."},
							cols = {"Level", "Health", "Experience", "Loot", "Damage"},
