		{
			id = "lore",
			name = "Lore",
			entries = {
				{
					id = "lore:cinders",
					name = "The Fall of the Cinders",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"No one agrees on the night it happened. The sky split, and burning stones fell like slow rain for a season. Where they struck, the ground remembered fire: forests turned to ash, the dead stirred in their graves, and the first rifts opened like wounds that would not close.", "The Cinders still lie where they fell. Some are cold. Some still beat."}
						},
						{
							h = "Em português",
							p = {"Ninguém concorda sobre a noite em que aconteceu. O céu se partiu e pedras em chamas caíram como uma chuva lenta por uma estação inteira. Onde tocaram, a terra lembrou o fogo: florestas viraram cinza, os mortos se agitaram nos túmulos e as primeiras fendas se abriram como feridas que não fecham.", "As Brasas ainda estão onde caíram. Algumas esfriaram. Outras ainda pulsam."}
						}
					}
				},
				{
					id = "lore:first_blood",
					name = "The Isle of First Blood",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Every newcomer wakes on the same small island, among statues no one remembers carving. The Vigil says the island was the first place a Cinder did not burn. Whatever the truth, nothing there can kill you, and nothing there will follow you out."}
						},
						{
							h = "Em português",
							p = {"Todo recém-chegado acorda na mesma pequena ilha, entre estátuas que ninguém lembra de ter esculpido. A Vigília diz que a ilha foi o primeiro lugar onde uma Brasa não queimou. Seja qual for a verdade, nada ali pode matar você, e nada dali o seguirá."}
						}
					}
				},
				{
					id = "lore:archive",
					name = "The Archivist's Ledger",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Archivist Maelis keeps a ledger of every name the fire gave back: bosses, rifts, Omens, the things in the deep. She pays for true accounts and burns the false ones. Her ink is mixed with ash, so that what is written cannot be unwritten."}
						},
						{
							h = "Em português",
							p = {"A Arquivista Maelis mantém um registro de cada nome que o fogo devolveu: chefes, fendas, Presságios, as coisas das profundezas. Ela paga por relatos verdadeiros e queima os falsos. Sua tinta é misturada com cinza, para que o que foi escrito não possa ser apagado."}
						}
					}
				},
				{
					id = "lore:rifts",
					name = "The Rifts",
					color = "#c9a27a",
					sub = "Rifts",
					group = "rift",
					f = {group = "rift"},
					sections = {
						{
							h = "Lore",
							p = {"A rift is a place that fell with a Cinder and never finished landing. Step through with a key and you walk a piece of somewhere else, for as long as it holds. Each one has a guardian. Seal it, and the rift closes. Leave it open, and it remembers your face."}
						},
						{
							h = "Em português",
							p = {"Uma fenda é um lugar que caiu com uma Brasa e nunca terminou de pousar. Atravesse com uma chave e você caminha por um pedaço de outro lugar, enquanto ele durar. Cada uma tem um guardião. Sele-a e a fenda se fecha. Deixe-a aberta e ela lembrará do seu rosto."}
						}
					}
				},
				{
					id = "lore:rift_abyssal",
					name = "Abyssal Rift",
					color = "#c9a27a",
					sub = "Rifts",
					group = "rift",
					f = {group = "rift"},
					sections = {
						{
							h = "Lore",
							p = {"Floors of black glass over nothing at all. The Veiled Choir hears singing down there and answers it. What lives in the Abyssal Rift has too many eyes, and it has learned to close the ones you are looking at."}
						},
						{
							h = "Em português",
							p = {"Pisos de vidro negro sobre o nada. O Coro Velado ouve um canto lá embaixo e responde. O que vive na Fenda Abissal tem olhos demais, e aprendeu a fechar aqueles para os quais você olha."}
						}
					}
				},
				{
					id = "lore:rift_obsidian",
					name = "Obsidian Hall",
					color = "#c9a27a",
					sub = "Rifts",
					group = "rift",
					f = {group = "rift"},
					sections = {
						{
							h = "Lore",
							p = {"A hall of black marble that was never built by hands. Magma runs in its seams like veins. The Cinderforge Compact mines its walls between waves of the things that guard it, and calls the losses the price of good steel."}
						},
						{
							h = "Em português",
							p = {"Um salão de mármore negro que nunca foi construído por mãos. O magma corre em suas juntas como veias. O Pacto da Forja de Brasa minera suas paredes entre as ondas de guardiões, e chama as perdas de preço do bom aço."}
						}
					}
				},
				{
					id = "lore:rift_ashen",
					name = "Ashen Crypt",
					color = "#c9a27a",
					sub = "Rifts",
					group = "rift",
					f = {group = "rift"},
					sections = {
						{
							h = "Lore",
							p = {"Graves that burned without being opened. The dead inside woke warm and angry. The Ashen Vigil rings its bells at every crypt that stirs, and sends wardens with oil and torches to finish what the fire started."}
						},
						{
							h = "Em português",
							p = {"Túmulos que queimaram sem serem abertos. Os mortos lá dentro acordaram quentes e furiosos. A Vigília Cinzenta toca seus sinos em cada cripta que se agita e envia guardiões com óleo e tochas para terminar o que o fogo começou."}
						}
					}
				},
				{
					id = "lore:rift_sanctum",
					name = "Forsaken Sanctum",
					color = "#c9a27a",
					sub = "Rifts",
					group = "rift",
					f = {group = "rift"},
					sections = {
						{
							h = "Lore",
							p = {"A gilded temple swallowed by fungus. Its priests prayed for the fire to pass them by, and something answered with rot instead. The Thornbound Circle cuts the blight back every season. Every season it grows faster."}
						},
						{
							h = "Em português",
							p = {"Um templo dourado engolido por fungos. Seus sacerdotes rezaram para que o fogo passasse longe, e algo respondeu com podridão. O Círculo dos Espinhos corta a praga a cada estação. A cada estação ela cresce mais rápido."}
						}
					}
				},
				{
					id = "lore:omens",
					name = "The Omens",
					color = "#c9a27a",
					sub = "Omens",
					group = "omen",
					f = {group = "omen"},
					sections = {
						{
							h = "Lore",
							p = {"Some rifts do not hold a guardian. They hold a herald. The fragments they leave can be pressed into a key, and the key opens a door to the Omen itself: Sangrith of the Bloodmoon, Morvane the Hollow Crown, Thalcyra the Stormbound Seer. Each one foretells the same thing in a different voice."}
						},
						{
							h = "Em português",
							p = {"Algumas fendas não guardam um guardião. Guardam um arauto. Os fragmentos que deixam podem ser prensados em uma chave, e a chave abre a porta para o próprio Presságio: Sangrith da Lua de Sangue, Morvane a Coroa Oca, Thalcyra a Vidente da Tempestade. Cada um prevê a mesma coisa com uma voz diferente."}
						}
					}
				},
				{
					id = "lore:omen_bloodmoon",
					name = "Sangrith the Bloodmoon Herald",
					color = "#c9a27a",
					sub = "Omens",
					group = "omen",
					f = {group = "omen"},
					sections = {
						{
							h = "Lore",
							p = {"Sangrith walked out of the red night that followed the first fall, carrying a sickle of moonlight. He harvests what the fire missed. Those who fight him say the floor fills with blood before anyone is cut."}
						},
						{
							h = "Em português",
							p = {"Sangrith saiu da noite vermelha que seguiu a primeira queda, carregando uma foice de luar. Ele colhe o que o fogo deixou para trás. Quem o enfrenta diz que o chão se enche de sangue antes que alguém seja ferido."}
						}
					}
				},
				{
					id = "lore:omen_hollow",
					name = "Morvane the Hollow Crown",
					color = "#c9a27a",
					sub = "Omens",
					group = "omen",
					f = {group = "omen"},
					sections = {
						{
							h = "Lore",
							p = {"Morvane was a queen once, of a kingdom that burned in one night. She kept the crown and lost the head beneath it. Her court of wraiths still bows to the empty throne, and they expect you to bow as well."}
						},
						{
							h = "Em português",
							p = {"Morvane foi rainha um dia, de um reino que queimou em uma única noite. Ela ficou com a coroa e perdeu a cabeça que a usava. Sua corte de espectros ainda se curva ao trono vazio, e espera que você se curve também."}
						}
					}
				},
				{
					id = "lore:omen_storm",
					name = "Thalcyra the Stormbound Seer",
					color = "#c9a27a",
					sub = "Omens",
					group = "omen",
					f = {group = "omen"},
					sections = {
						{
							h = "Lore",
							p = {"Thalcyra looked into the falling sky to read what came after, and the sky looked back. Now she is the storm she saw. Lightning finds the ground she marks a breath before it falls. Read the marks, or join her vision."}
						},
						{
							h = "Em português",
							p = {"Thalcyra olhou para o céu em queda para ler o que viria depois, e o céu olhou de volta. Agora ela é a tempestade que viu. O raio encontra o chão que ela marca um instante antes de cair. Leia as marcas, ou entre em sua visão."}
						}
					}
				},
				{
					id = "lore:omen_ascended",
					name = "The Ascended Omens and the Ember Gate",
					color = "#c9a27a",
					sub = "Omens",
					group = "omen",
					f = {group = "omen"},
					sections = {
						{
							h = "Lore",
							p = {"An Omen that is slain does not stay slain. Bind three shards of its herald into a sigil and it returns, Ascended, behind the Ember Gate. The fallen wait in the antechamber for the Gate to let them back. It always does, until it does not."}
						},
						{
							h = "Em português",
							p = {"Um Presságio abatido não continua abatido. Una três fragmentos do seu arauto em um sigilo e ele retorna, Ascendido, atrás do Portão de Brasa. Os caídos esperam na antecâmara até que o Portão os deixe voltar. Ele sempre deixa, até o dia em que não deixa."}
						}
					}
				},
				{
					id = "lore:cinderheart",
					name = "Ysgrath the Cinderheart",
					color = "#c9a27a",
					sub = "Omens",
					group = "omen",
					f = {group = "omen"},
					sections = {
						{
							h = "Lore",
							p = {"Every Omen sings of one thing: the first Cinder, the one that never cooled. It has a name now, Ysgrath, and a heartbeat you can feel through the soles of your boots. It remembers the red night, the hollow court and the storm, because it made them. Only those who have ended all three may stand before it."}
						},
						{
							h = "Em português",
							p = {"Todo Presságio canta sobre uma só coisa: a primeira Brasa, a que nunca esfriou. Agora ela tem um nome, Ysgrath, e um batimento que se sente pela sola das botas. Ela lembra a noite vermelha, a corte oca e a tempestade, porque foi ela que os criou. Só quem encerrou os três pode ficar diante dela."}
						}
					}
				},
				{
					id = "lore:sepulchre",
					name = "The Ashen Sepulchre",
					color = "#c9a27a",
					sub = "The Ashen Sepulchre",
					group = "raid",
					f = {group = "raid"},
					sections = {
						{
							h = "Lore",
							p = {"The Sepulchre was not built to honour a king. It was built to hold one. Varkhul, the Ashen Sovereign, ruled until the fire made him something that would not die, and his own wardens walled him in with everything that served him. Gravewarden Ulthar still keeps the first gate. Morwen the Ash-Sister still sings. The last door opens from the inside."}
						},
						{
							h = "Em português",
							p = {"O Sepulcro não foi construído para honrar um rei. Foi construído para prendê-lo. Varkhul, o Soberano Cinzento, reinou até que o fogo o transformou em algo que não morre, e seus próprios guardiões o emparedaram com tudo o que o servia. O Guardião de Túmulos Ulthar ainda vigia o primeiro portão. Morwen, a Irmã das Cinzas, ainda canta. A última porta se abre por dentro."}
						}
					}
				},
				{
					id = "lore:wb_kaelgor",
					name = "Kaelgor the Infernal Warlord",
					color = "#c9a27a",
					sub = "World bosses",
					group = "worldboss",
					f = {group = "worldboss"},
					sections = {
						{
							h = "Lore",
							p = {"Kaelgor led the first army through a burning rift and found nothing on the other side worth conquering, so he conquers ours, again and again. His banner is a sheet of flame. His soldiers are whoever he killed last time."}
						},
						{
							h = "Em português",
							p = {"Kaelgor liderou o primeiro exército através de uma fenda em chamas e não encontrou do outro lado nada que valesse conquistar; então conquista o nosso, de novo e de novo. Seu estandarte é uma cortina de fogo. Seus soldados são quem ele matou da última vez."}
						}
					}
				},
				{
					id = "lore:wb_skaldra",
					name = "Skaldra the Rime Queen",
					color = "#c9a27a",
					sub = "World bosses",
					group = "worldboss",
					f = {group = "worldboss"},
					sections = {
						{
							h = "Lore",
							p = {"Where a Cinder fell into the northern ice, the ice did not melt. It woke. Skaldra wears the cold like a gown and freezes the sky wherever she descends. She hates the fire more than any of us. That does not make her a friend."}
						},
						{
							h = "Em português",
							p = {"Onde uma Brasa caiu no gelo do norte, o gelo não derreteu. Ele despertou. Skaldra veste o frio como um vestido e congela o céu onde quer que desça. Ela odeia o fogo mais do que qualquer um de nós. Isso não a torna uma aliada."}
						}
					}
				},
				{
					id = "lore:wb_rotmother",
					name = "The Rotmother",
					color = "#c9a27a",
					sub = "World bosses",
					group = "worldboss",
					f = {group = "worldboss"},
					sections = {
						{
							h = "Lore",
							p = {"The plague pits were dug for the dead of the first fall. Something kept feeding on them after the digging stopped, and grew, and gave birth. The Thornbound Circle burns its brood on sight and still cannot find the pit it crawls out of."}
						},
						{
							h = "Em português",
							p = {"As covas da peste foram cavadas para os mortos da primeira queda. Algo continuou se alimentando deles depois que pararam de cavar, e cresceu, e deu à luz. O Círculo dos Espinhos queima sua ninhada assim que a vê e ainda não encontrou a cova de onde ela rasteja."}
						}
					}
				},
				{
					id = "lore:wb_nyxareth",
					name = "Nyxareth the Void Archon",
					color = "#c9a27a",
					sub = "World bosses",
					group = "worldboss",
					f = {group = "worldboss"},
					sections = {
						{
							h = "Lore",
							p = {"The Veiled Choir sang to the void for a hundred nights. On the hundred and first, the void sang back, and Nyxareth stepped out of the tear. The Choir calls it a misunderstanding. The Vigil calls it a debt."}
						},
						{
							h = "Em português",
							p = {"O Coro Velado cantou para o vazio por cem noites. Na centésima primeira, o vazio cantou de volta, e Nyxareth saiu do rasgo. O Coro chama isso de mal-entendido. A Vigília chama de dívida."}
						}
					}
				},
				{
					id = "lore:wb_vharok",
					name = "Vharok the Blood Colossus",
					color = "#c9a27a",
					sub = "World bosses",
					group = "worldboss",
					f = {group = "worldboss"},
					sections = {
						{
							h = "Lore",
							p = {"Vharok is what a battlefield becomes when no one buries the fallen. Every war since the first fall added to him. When the earth trembles, he is counting the new dead."}
						},
						{
							h = "Em português",
							p = {"Vharok é o que um campo de batalha se torna quando ninguém enterra os caídos. Cada guerra desde a primeira queda aumentou seu corpo. Quando a terra treme, ele está contando os novos mortos."}
						}
					}
				},
				{
					id = "lore:descent",
					name = "The Ember Descent",
					color = "#c9a27a",
					sub = "The deep places",
					group = "deep",
					f = {group = "deep"},
					sections = {
						{
							h = "Lore",
							p = {"Under every town there is a stair that was not there before the fall. It goes down further each time someone walks it. The rooms change. The heat does not. No one has found the bottom, and those who claim to have found it do not go back."}
						},
						{
							h = "Em português",
							p = {"Sob cada cidade há uma escada que não existia antes da queda. Ela desce mais a cada vez que alguém a percorre. As salas mudam. O calor não. Ninguém encontrou o fundo, e quem diz ter encontrado não volta lá."}
						}
					}
				},
				{
					id = "lore:deep_wardens",
					name = "The Wardens of the Deep",
					color = "#c9a27a",
					sub = "The deep places",
					group = "deep",
					f = {group = "deep"},
					sections = {
						{
							h = "Lore",
							p = {"Past the reach of any map lie places the fire hollowed out on its own: the Emberdeep Hollows, the Sunken Ossuary, the Cinderfall Wastes, the Hollow Vault. Each has a keeper grown fat on Cinder heat: the Emberdeep Maw, the Ossuary Warden, Cinderwing, and Vault Keeper Ossrim, who still counts coins no one will spend."}
						},
						{
							h = "Em português",
							p = {"Além do alcance de qualquer mapa ficam lugares que o fogo escavou sozinho: Emberdeep Hollows, Sunken Ossuary, Cinderfall Wastes e The Hollow Vault. Cada um tem um guardião engordado pelo calor das Brasas: The Emberdeep Maw, The Ossuary Warden, Cinderwing e Vault Keeper Ossrim, que ainda conta moedas que ninguém vai gastar."}
						}
					}
				},
				{
					id = "lore:deep_dungeons",
					name = "The Four Deeper Doors",
					color = "#c9a27a",
					sub = "The deep places",
					group = "deep",
					f = {group = "deep"},
					sections = {
						{
							h = "Lore",
							p = {"Below the Vault the fire kept digging. The Marrow Crypts, where Ossivane the Gravecage walks on the ribs of a dead giant. The Iron Crucible, whose Forgewarden Kharzun still guards a forge no hand works. The Fallen Sanctum, where Vaelith sings what is left of a hymn. And last the Pyre Throne, where Azhkarrath, mother of the pyrewings, lies chained to the seat she burned. Each door opens to one at a time."}
						},
						{
							h = "Em português",
							p = {"Abaixo do Vault o fogo continuou cavando. The Marrow Crypts, onde Ossivane the Gravecage anda sobre as costelas de um gigante morto. The Iron Crucible, cujo Forgewarden Kharzun ainda guarda uma forja que nenhuma mão trabalha. The Fallen Sanctum, onde Vaelith canta o que restou de um hino. E por último The Pyre Throne, onde Azhkarrath, mãe dos pyrewings, jaz acorrentada ao trono que queimou. Cada porta se abre para um de cada vez."}
						}
					}
				},
				{
					id = "lore:cellars",
					name = "The Cellars of Cinderhold",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Cinderhold was built on top of an older town, and the older town was built on its cellars. The Archivist keeps the overflow of her ledger down there, in dry rooms the rats think are theirs. Every year she loses a king or two to their teeth, and every year she writes them again from memory."}
						},
						{
							h = "Em português",
							p = {"Cinderhold foi construída sobre uma cidade mais antiga, e a cidade mais antiga foi construída sobre seus porões. A Arquivista guarda lá embaixo o que não cabe em seu registro, em salas secas que os ratos acham que são deles. Todo ano ela perde um rei ou dois para os dentes deles, e todo ano os escreve de novo de memória."}
						}
					}
				},
				{
					id = "lore:lantern_road",
					name = "The Lantern Road",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Before the Cinders, the Ashen Vigil lit a lantern on every grave between the towns, so the dead would know the way to rest. The road of lights ran from coast to coast. The night the sky split, every lantern went out at once, and the dead have been walking the dark road ever since, looking for the next light.", "At its end stands a roost of stone watchers, and past them, a circle of open graves."}
						},
						{
							h = "Em português",
							p = {"Antes das Brasas, a Vigília Cinzenta acendia uma lanterna em cada túmulo entre as cidades, para que os mortos soubessem o caminho do descanso. A estrada de luzes ia de costa a costa. Na noite em que o céu se partiu, todas as lanternas se apagaram de uma vez, e desde então os mortos andam pela estrada escura procurando a próxima luz.", "No fim dela há um poleiro de vigias de pedra e, além deles, um círculo de túmulos abertos."}
						}
					}
				},
				{
					id = "lore:grave_circle",
					name = "The Grave Circle",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Some saw the Cinders as a curse. The Grave Circle saw them as a gift: a fire that wakes the dead is a fire that can be taught. Its necromancers raise bonebeasts from the Vigil's own graves, and their liches and banshees keep a list of every name the Circle means to wake. The Archivist's name was on it. So, they say, was yours."}
						},
						{
							h = "Em português",
							p = {"Alguns viram as Brasas como uma maldição. O Círculo das Covas as viu como um presente: um fogo que desperta os mortos é um fogo que pode ser ensinado. Seus necromantes erguem bestas de ossos dos próprios túmulos da Vigília, e seus liches e banshees mantêm uma lista de cada nome que o Círculo pretende despertar. O nome da Arquivista estava nela. O seu também, dizem."}
						}
					}
				},
				{
					id = "lore:dragon_census",
					name = "The Dragon Census",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"The Veiled Choir counts dragons the way farmers count clouds. A brood that grows means a hot year and burning fields; a brood that shrinks means something larger is eating them. The census is sung, never written, so the Archivist keeps the only copy on paper. She binds it with rune shards, because dragon fire eats ordinary glue."}
						},
						{
							h = "Em português",
							p = {"O Coro Velado conta dragões como fazendeiros contam nuvens. Uma ninhada que cresce significa um ano quente e campos queimando; uma ninhada que diminui significa que algo maior está comendo os dragões. O censo é cantado, nunca escrito, então a Arquivista guarda a única cópia em papel. Ela a encaderna com fragmentos rúnicos, porque o fogo de dragão come cola comum."}
						}
					}
				},
				{
					id = "lore:moon_sick",
					name = "The Moon-Sick",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Under a Cinder moon some hunters do not come home as hunters. The Thornbound Circle calls them the moon-sick and keeps a place at its table for each of them, in case they return. None ever has. Bramwyn says they run from something in the marsh, a mother of a hundred heads, and that the moon only shows them the way."}
						},
						{
							h = "Em português",
							p = {"Sob uma lua de Brasa, alguns caçadores não voltam para casa como caçadores. O Círculo Espinhoso os chama de enfermos da lua e mantém um lugar à mesa para cada um deles, caso voltem. Nenhum voltou. Bramwyn diz que fogem de algo no pântano, uma mãe de cem cabeças, e que a lua apenas lhes mostra o caminho."}
						}
					}
				},
				{
					id = "lore:bone_court",
					name = "The Bone Court",
					color = "#c9a27a",
					sub = "The world",
					group = "world",
					f = {group = "world"},
					sections = {
						{
							h = "Lore",
							p = {"Long before the Ashen Sepulchre had its Sovereign, the Bone Court had its own king, and a court of archers, berserkers and masters who served him past death. The Vigil buried them twice. The Cinders woke them twice. Their records are sealed now in the Archivist's ledger with rune shards, so that the court is only a page, and pages do not march."}
						},
						{
							h = "Em português",
							p = {"Muito antes de o Sepulcro Cinzento ter seu Soberano, a Corte de Ossos tinha seu próprio rei, e uma corte de arqueiros, berserkers e mestres que o serviram além da morte. A Vigília os enterrou duas vezes. As Brasas os despertaram duas vezes. Seus registros agora estão selados no registro da Arquivista com fragmentos rúnicos, para que a corte seja só uma página, e páginas não marcham."}
						}
					}
				},
				{
					id = "lore:chronicle_s1",
					name = "The Ashen Chronicle: Season of Ash",
					color = "#c9a27a",
					sub = "The Ashen Chronicle",
					group = "chronicle",
					f = {group = "chronicle"},
					sections = {
						{
							h = "The Ashen Chronicle",
							p = {"The ash has always fallen on the broken world. This season it falls heavier and warmer, and Archivist Maelis, the Chronicler, has opened a new book. What the whole realm does together is written in it, and the world answers.", "One chapter is open at a time. The whole realm writes it: every world boss slain, rift sealed, Omen and Ascended Omen defeated, Ashen Sepulchre cleared, character reaching a level and world event won counts for the chapter whose goal it is. When every goal is met the chapter is written and the world changes. Adventure > Chronicle shows the bars, your part and the top contributors."}
						},
						{
							h = "Chapters",
							cols = {"Chapter", "Goals"},
							w = {70, 30},
							rows = {
								{"I. The Ash Thickens", "2 goals"},
								{"II. The Wound Beside the Walls", "2 goals"},
								{"III. Omens in the Ashfall", "2 goals"},
								{"IV. The Sepulchre Stirs", "2 goals"},
								{"V. Embers Rekindled", "3 goals"}
							}
						},
						{
							h = "At the season's end",
							p = {"The Chronicler records the top contributors of every chapter: the client's Record tab and the website's Chronicle page keep them. The next season starts a new book, and the world changes of this one are taken back."}
						},
						{
							h = "Em português",
							p = {"A Crônica das Cinzas: Temporada das Cinzas", "As cinzas sempre caíram sobre o mundo partido. Nesta temporada elas caem mais grossas e mais quentes, e a Arquivista Maelis, a Cronista, abriu um livro novo. O que o reino inteiro fizer junto será escrito nele, e o mundo vai responder."}
						}
					}
				},
				{
					id = "lore:chronicle_s1_1",
					name = "I. The Ash Thickens",
					color = "#c9a27a",
					sub = "The Ashen Chronicle: Season of Ash",
					group = "chronicle",
					f = {group = "chronicle"},
					sections = {
						{
							h = "The story",
							p = {"The ash falls warm to the touch now, and in the capital's streets the wind no longer carries it away. Beyond the walls the small rifts open faster than the Vigil's wardens can count them.", "The Chronicler has written one line on the first page: \"The world remembers what it does.\" Turn the keys. Seal the small wounds before they learn to grow, and let the new hunters find their strength."}
						},
						{
							h = "Goals of the realm",
							cols = {"Goal", "Target"},
							w = {75, 25},
